  world.on('damaged', ({ cause, amount, critical }) => {
    if (cause !== 'melee') return;
    const dmg = Number(amount) || 0;
    if (dmg < 1) return;
    // Amplitude: 1.0 at 1dmg, ramps to ~5 at 15+dmg, crits get 1.4x
